INSERT INTO questions (point_code, title, option_a, option_b, option_c, option_d, correct_option, explanation, enabled, created_at) VALUES
('ALL','健步走过程中，以下哪种做法更安全？','边走边低头看手机','穿舒适防滑运动鞋','随意横穿道路','感觉头晕仍坚持冲刺','B','健步走应穿舒适、防滑的运动鞋，注意观察周边环境。',1,datetime('now')),
('ALL','活动中如身体不适，正确做法是？','继续坚持到终点','自行离队不告知','立即停止并联系工作人员','加快速度尽快完成','C','身体不适应立即停止活动并联系现场工作人员。',1,datetime('now')),
('ALL','补水时更推荐的方式是？','长时间不喝水','一次性大量饮水','少量多次饮水','只喝冰饮料','C','运动中建议少量多次补水。',1,datetime('now')),
('cp1','到达第一个点位时，正确的打点要求是？','可以让别人代扫','本人扫码并完成答题','只拍照不扫码','回到终点再补扫','B','打点应由本人扫码完成。',1,datetime('now')),
('cp1','集体健步走时，应保持怎样的队形？','随意拥挤','横排占满道路','保持适当间距','逆行穿插','C','保持适当间距有助于防止碰撞和摔倒。',1,datetime('now')),
('cp2','经过道路或交叉口时，正确做法是？','观察确认安全后通过','边跑边通过','低头看手机通过','跟着别人冲过去','A','通过道路时应先观察并确认安全。',1,datetime('now')),
('cp2','活动中发现他人摔倒，首先应？','围观拍照','立即冲刺离开','提醒后方并联系工作人员','不理会继续前进','C','应提醒后方人员并及时联系工作人员处理。',1,datetime('now')),
('cp3','临近终点时，以下哪种做法正确？','突然冲刺超越人群','按秩序行进并回起点签退','不签退直接离开','代替队友签退','B','完成三个点位后应回起点按秩序签退。',1,datetime('now')),
('cp3','完成活动后，正确的整理方式是？','马上坐下不动','适当放松拉伸','大量饮用冰水','立即剧烈运动','B','运动后可适当放松拉伸，帮助身体恢复。',1,datetime('now'));
